PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS protocols(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),name TEXT NOT NULL,draft_xml TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS protocol_versions(id TEXT PRIMARY KEY,protocol_id TEXT NOT NULL REFERENCES protocols(id),version INTEGER NOT NULL,xml_source TEXT NOT NULL,checksum TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(protocol_id,version));
CREATE TRIGGER IF NOT EXISTS immutable_protocol_update BEFORE UPDATE ON protocol_versions BEGIN SELECT RAISE(ABORT,'published protocol is immutable'); END;
CREATE TABLE IF NOT EXISTS entities(project_id TEXT NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,id TEXT NOT NULL,json TEXT NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(project_id,kind,id));
CREATE TABLE IF NOT EXISTS packets(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL REFERENCES projects(id),event_time INTEGER NOT NULL,direction TEXT NOT NULL,endpoint_id TEXT NOT NULL,remote TEXT NOT NULL,protocol_id TEXT NOT NULL,msg_code INTEGER,byte_length INTEGER NOT NULL,hex TEXT NOT NULL,status TEXT NOT NULL,decoded_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS packet_project_time ON packets(project_id,id DESC);
CREATE INDEX IF NOT EXISTS packet_filter ON packets(project_id,msg_code,direction);
CREATE TABLE IF NOT EXISTS event_log(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id TEXT NOT NULL,event_time INTEGER NOT NULL,event_type TEXT NOT NULL,entity_id TEXT NOT NULL,metadata_json TEXT NOT NULL);
PRAGMA user_version=1;
